        Ok(Self::published()
            .select_only()
            .column(articles::Column::TagList)
            .into_tuple::<Value>()
            .all(db)
            .await?
            .into_iter()
            .flat_map(|tags| serde_json::from_value::<Vec<String>>(tags).unwrap_or_default())
            .collect())
    }
}

