use clap::ValueEnum;
use futures_util::FutureExt;
use serde::{Deserialize, Serialize};
use serde_json::Value as JsonValue;
use serde_variant::to_variant_name;
#[cfg(feature = "worker")]
pub mod pg;
#[cfg(feature = "worker_redis")]
pub mod redis;
#[cfg(feature = "worker")]
pub(crate) mod sql;
