/// Configuration for an opt-in visibility-timeout reaper.
///
/// When set on a queue config, the queue provider spawns a background task
/// that periodically requeues jobs stuck in `Processing` for longer than
/// `age_minutes` (for example, because the worker that dequeued them
/// crashed before completing or failing them). It reuses the same requeue
/// logic as `cargo loco jobs requeue`.
///
/// This is entirely opt-in: leaving `reaper` unset (`None`, the default)
/// keeps existing behavior unchanged and no background task is spawned.
///
/// ```yaml
/// queue:
///   kind: Postgres
///   uri: "{{ get_env(name=\"LOCO_QUEUE_URL\", default=\"postgres://localhost:5432/loco_app\") }}"
///   # Optional: automatically requeue jobs stuck in `processing` (e.g. after a worker crash).
///   # reaper:
///   #   age_minutes: 10
///   #   interval_seconds: 60
/// ```
#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct ReaperConfig {
    /// Requeue jobs that have been in the `processing` state for longer than
    /// this many minutes.
    pub age_minutes: i64,

    /// How often, in seconds, the reaper sweeps for stale jobs.
    #[serde(default = "default_reaper_interval_seconds")]
    pub interval_seconds: u64,
}

fn pgq_poll_interval() -> u32 {
    1
}

#[cfg(feature = "db-sqlite")]
fn sqlt_poll_interval() -> u32 {
    1
}

fn num_workers() -> u32 {
    2
}

fn default_reaper_interval_seconds() -> u64 {
    60
}

/// When could not initialize the application.
pub async fn start<H: Hooks>(
    boot: BootResult,
    server_config: ServeParams,
    no_banner: bool,
) -> Result<()> {
    if boot.run_scheduler {
        let scheduler = scheduler::<H>(&boot.app_context, None, None, None)?;
        tokio::spawn(async move {
            if let Err(err) = scheduler.run().await {
                error!(err = err.to_string(), "error while running scheduler");
            }
        });
    }

    if !no_banner {
        print_banner(&boot, &server_config);
    }

    let BootResult {
        router,
        worker,
        run_scheduler: _,
        app_context,
    } = boot;

    match (router, worker) {
        (Some(router), None) => {
            H::serve(router, &app_context, &server_config).await?;
        }
        (Some(router), Some(tags)) => {
            let handle = if app_context.config.workers.mode == WorkerMode::BackgroundQueue {
                Some(start_queue_worker(&app_context, tags)?)
            } else {
                None
            };

            H::serve(router, &app_context, &server_config).await?;

            if let Some(handle) = handle {
                shutdown_and_await_queue_worker(&app_context, handle).await?;
            }
        }
        (None, Some(tags)) => {
            let handle = if app_context.config.workers.mode == WorkerMode::BackgroundQueue {
                Some(start_queue_worker(&app_context, tags)?)
            } else {
                None
            };

            await_shutdown_then_run_hook::<H>(&app_context, shutdown_signal()).await;

            if let Some(handle) = handle {
                shutdown_and_await_queue_worker(&app_context, handle).await?;
            }
        }
        _ => {}
    }
    Ok(())
}

/// Waits for `shutdown` to resolve, then runs [`Hooks::on_shutdown`].
///
/// This is used by the worker-only / worker-and-scheduler start modes, which
/// (unlike the server modes) have no Axum graceful-shutdown hook of their own
/// to invoke `on_shutdown` from. Extracted out of [`start`] purely so the
    H::before_run(&app_context).await?;
